import java.util.Scanner;

public class Main {
    // 预处理最大位数
    static final int MAX_LEN = 25;

    // 首位和其他位可选数字
    static int[] FIRST = {1, 2, 4, 5, 6, 7, 8, 9};
    static int[] OTHER = {0, 1, 2, 4, 5, 6, 7, 8, 9};

    // suf[i][r]：还剩i位要填，当前前缀模3为r时，最终能组成多少个合法数
    static long[][] suf = new long[MAX_LEN + 1][3];

    // cnt[len]：恰好len位的喜欢的数个数
    static long[] cnt = new long[MAX_LEN + 1];

    // 预处理
    static void init() {
        // 边界：没有位可填时，当前数模3不为0才合法
        for (int r = 0; r < 3; r++) {
            suf[0][r] = (r != 0) ? 1 : 0;
        }

        // 预处理后缀方案数
        for (int i = 1; i <= MAX_LEN; i++) {
            for (int r = 0; r < 3; r++) {
                long total = 0;
                for (int d : OTHER) {
                    int nr = (r * 10 + d) % 3;
                    total += suf[i - 1][nr];
                }
                suf[i][r] = total;
            }
        }

        // 统计每种长度的合法数个数
        for (int len = 1; len <= MAX_LEN; len++) {
            long total = 0;
            for (int d : FIRST) {
                total += suf[len - 1][d % 3];
            }
            cnt[len] = total;
        }
    }

    // 求第k个喜欢的数
    static String kthNumber(long k) {
        int len = 1;
        while (k > cnt[len]) {
            k -= cnt[len];
            len++;
        }

        StringBuilder ans = new StringBuilder();
        int curMod = 0;

        // 按位构造答案
        for (int pos = 0; pos < len; pos++) {
            int[] digits = (pos == 0) ? FIRST : OTHER;
            int rest = len - pos - 1;

            for (int d : digits) {
                int nxtMod = (curMod * 10 + d) % 3;
                long ways = suf[rest][nxtMod];

                if (k > ways) {
                    k -= ways;
                } else {
                    ans.append(d);
                    curMod = nxtMod;
                    break;
                }
            }
        }

        return ans.toString();
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        init();

        int t = sc.nextInt();
        while (t-- > 0) {
            long k = sc.nextLong();
            System.out.println(kthNumber(k));
        }
        sc.close();
    }
}
